<template><view class="page"><view v-for="p in pets" :key="p.id" class="card pet-card" @tap="goDetail(p)"><view class="pet-avatar" :class="p.type==='cat'?'cat-bg':'dog-bg'">{{p.type==='cat'?'🐱':'🐶'}}</view><view class="pet-info"><view class="pet-name">{{p.name}}</view><view class="pet-detail">{{p.breed||(p.type==='cat'?'猫咪':'狗狗')}} · {{p.fence_radius}}m围栏</view></view><view class="pet-status" :class="p.fence_enabled?'on':'off'">{{p.fence_enabled?'🛡围栏':'○离线'}}</view></view><view v-if="pets.length===0" class="empty">还没有宠物</view></view></template>
<script setup lang="ts">import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import {http} from '@/utils/request';const pets=ref<any[]>([]);onShow(async()=>{try{const d=await http.get<any[]>('/pets');pets.value=d||[]}catch(e){}});function goDetail(p:any){uni.navigateTo({url:"/pages/pet-detail/pet-detail?id="+p.id})}</script>
<style scoped>.page{min-height:100vh;background:#f6f7fb;padding:24rpx}.pet-card{display:flex;align-items:center;gap:20rpx;margin-bottom:16rpx}.pet-avatar{width:88rpx;height:88rpx;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:44rpx}.cat-bg{background:#fff7ed}.dog-bg{background:#eff6ff}.pet-info{flex:1}.pet-name{font-size:30rpx;font-weight:700}.pet-detail{font-size:24rpx;color:#9aa0a6}.pet-status{font-size:22rpx;padding:6rpx 16rpx;border-radius:999rpx}.pet-status.on{background:#f0fdf4;color:#22c55e}.pet-status.off{background:#f3f4f6;color:#9aa0a6}.empty{text-align:center;color:#9aa0a6;padding:80rpx 0}</style>